  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exquisite control of atoms with a major advance in precision measurement, enabling tests of fundamental physics and new forms of geodesy. The work has opened a broad and productive field.",
        "attribution": "Katori and Ye are central, independent pioneers of the optical lattice clock. Their complementary approaches support shared recognition.",
        "maturity": "The clocks have undergone decades of experimental refinement and independent comparison, with demonstrated accuracy and stability at the frontier of measurement.",
        "uncertainties": [
          "The division of credit between the original concepts, key demonstrations, and later advances is difficult to capture in two laureates."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics brought coherent light–matter interaction into an engineered solid-state system and became a foundation for superconducting quantum information processing.",
        "attribution": "Blais provided key theoretical foundations, while Wallraff and Schoelkopf led defining experimental demonstrations and development of the platform. The three contributions are distinct and complementary.",
        "maturity": "The central effects are robustly established across many laboratories, and the platform has supported increasingly capable experiments over more than two decades.",
        "uncertainties": [
          "The broader history includes important contributions from several groups, so a three-person attribution would necessarily be selective."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can be protected despite noise, changing the prospects for quantum computation and shaping a large experimental and theoretical field.",
        "attribution": "Shor and Steane established pivotal early codes, while Kitaev developed the topological code framework and related fault-tolerant ideas. These are influential, identifiable contributions.",
        "maturity": "The theory is secure and experimental demonstrations of error correction and fault tolerance have accumulated, although scalable, broadly useful quantum computers remain a work in progress.",
        "uncertainties": [
          "The field's foundational contributions extend well beyond these three, and the precise boundary between discovery and subsequent development is debatable."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum simulation of many-body systems possible and gave experimental access to phenomena that are difficult to study in solids.",
        "attribution": "Bloch and Greiner led landmark experiments, while Zoller helped establish the theoretical vision and methods. Their contributions span the essential theory–experiment connection.",
        "maturity": "The platform has produced reproducible results across many groups and remains highly productive. Its explanatory reach for particular materials and phases continues to develop.",
        "uncertainties": [
          "The proposal combines a broad program with multiple milestones, making the boundaries of the specific prizeworthy achievement uncertain."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computation joined precise control of individual atoms with a scalable quantum information architecture, becoming a leading experimental route to coherent quantum processing.",
        "attribution": "Cirac and Zoller made foundational theoretical contributions to the architecture, and Blatt demonstrated key operations and advanced the experimental platform.",
        "maturity": "Ion control and entangling operations have been established with exceptional precision and reproduced widely. Large-scale fault-tolerant operation is still under development.",
        "uncertainties": [
          "This overlaps substantially with the broader atomic quantum information and simulation contribution, and credit across the early trapped-ion field is extensive."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers created exceptionally bright, short-pulse coherent sources, enabling measurements of ultrafast dynamics and structure at atomic length scales.",
        "attribution": "Pellegrini, Rossbach, and Kim made major contributions to the concepts and accelerator designs that led to these facilities, though the achievement necessarily involved large teams.",
        "maturity": "The facilities have operated successfully for years and enabled a wide range of reproducible science.",
        "uncertainties": [
          "The intellectual and technical contributions were distributed across many researchers and institutions, complicating individual attribution."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Shinji Yuasa",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Giant tunnel magnetoresistance in solid-state junctions provided an important physical basis for magnetic read heads and spintronic devices, with substantial technological impact.",
        "attribution": "Moodera and the Japanese groups led by Yuasa and Miyazaki made independent, influential demonstrations of large effects in practical junctions.",
        "maturity": "The effect is well established and widely applied. Its technological importance is clear, although the underlying discovery has been recognized in closely related work.",
        "uncertainties": [
          "The relationship to earlier giant magnetoresistance work and prior prize recognition makes the scope and novelty of a separate award less clear."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "Atomic-resolution force microscopy extended local measurement of surfaces to unprecedented precision and enabled direct study of atomic-scale structure and interactions.",
        "attribution": "Giessibl established the qPlus sensor approach, while Meyer and Gross demonstrated and extended atomic-resolution imaging and chemical sensitivity.",
        "maturity": "The method has been independently reproduced and used broadly in surface science, although its influence is concentrated in a specialized area.",
        "uncertainties": [
          "The proposal joins instrument development with later scientific capabilities, and the relative weight of each contribution is uncertain."
        ]
      }
    }
  ]
}
